import { expect, test, uniqueName } from "../../fixtures";

test.describe("review vendors", () => {
  test("submitting with missing documents lists what is missing", { tag: "@REV-02" }, async ({ apiAs }) => {
    // Arrange
    const member = await apiAs("member");
    const vendorRes = await member.post("/api/vendors", {
      data: { name: uniqueName("REV-02 Vendor"), category: "services", contact_email: "ops@rev02.example.com" },
    });
    expect(vendorRes.status(), await vendorRes.text()).toBe(201);
    const vendor = (await vendorRes.json()) as { id: string };

    const uploadRes = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "w9",
        file: {
          name: "w9.txt",
          mimeType: "text/plain",
          buffer: Buffer.from("Legal Name: Harborline Logistics LLC\nTax ID: 84-2219067\nBusiness Type: LLC\n"),
        },
      },
    });
    expect(uploadRes.status(), await uploadRes.text()).toBe(201);
    const document = (await uploadRes.json()) as { id: string };

    await expect
      .poll(async () => {
        const res = await member.get(`/api/documents/${document.id}`);
        return ((await res.json()) as { status: string }).status;
      }, { message: "w9 extraction should finish" })
      .toBe("extracted");

    // Act
    const response = await member.post(`/api/vendors/${vendor.id}/submit`);

    // Assert
    const body = await response.text();
    expect(response.status(), body).toBe(409);
    const error = (JSON.parse(body) as { error: { code: string; missing_kinds: string[] } }).error;
    expect(error.code, body).toBe("documents_incomplete");
    expect(error.missing_kinds, body).toEqual(["contract", "insurance_certificate"]);
  });
});
